<?= $this->include('partials/header') ?>
<main class="dc-content"><div class="dc-page-heading"><div><h1 class="dc-page-title">Calendário</h1><p class="dc-page-subtitle">Pagamentos previstos, entregas esperadas e chegadas ao vendedor.</p></div></div>
<form class="card dc-filter-bar mb-3" method="get" action="/calendario"><div class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label" for="month">Mês</label><input class="form-control" id="month" type="month" name="month" value="<?= esc($month) ?>"></div><div class="col-md-2"><button class="btn btn-primary w-100">Ver calendário</button></div></div></form>
<section class="card"><div class="card-body border-bottom"><h2 class="dc-panel-title"><?= esc(date('m/Y', strtotime($month . '-01'))) ?></h2></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Data</th><th>Evento</th><th>Tipo</th><th class="text-end">Ação</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><?= date('d/m/Y', strtotime($event['date'])) ?></td><td><?= esc($event['title']) ?></td><td><span class="badge <?= $event['type'] === 'Pagamento' ? 'text-bg-warning' : ($event['type'] === 'Entrega' ? 'text-bg-primary' : 'text-bg-success') ?>"><?= esc($event['type']) ?></span></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= esc($event['url']) ?>">Abrir</a></td></tr><?php endforeach ?><?php if ($events === []): ?><tr><td colspan="4" class="text-center text-secondary py-5">Nenhum compromisso neste mês.</td></tr><?php endif ?></tbody></table></div></section></main>
<?= $this->include('partials/footer') ?>
